import{_ as t,o as a,c as r,a2 as o}from"./chunks/framework.CqGS6Fr9.js";const u=JSON.parse('{"title":"Testing and acceptance","description":"","frontmatter":{"pageId":"developers/testing","contentRevision":2},"headers":[],"relativePath":"en/developers/testing.md","filePath":"en/developers/testing.md"}'),i={name:"en/developers/testing.md"};function s(n,e,c,d,l,h){return a(),r("div",null,[...e[0]||(e[0]=[o('<h1 id="testing-and-acceptance" tabindex="-1">Testing and acceptance <a class="header-anchor" href="#testing-and-acceptance" aria-label="Permalink to &quot;Testing and acceptance&quot;">​</a></h1><p>Applies to: Rimlink 0.8.1 · RimWorld 1.7 · protocol 1.</p><h2 id="usage" tabindex="-1">Usage <a class="header-anchor" href="#usage" aria-label="Permalink to &quot;Usage {#usage}&quot;">​</a></h2><p>First reproduce the case and observe a failing targeted test, then make the minimal fix and rerun. Server tests use a real WebApplicationFactory; client-core tests talk to a test server. Full suite: dotnet test Rimlink.sln -nologo -v q.</p><p>Open returning is not proof that the peer attached: assert on received events. Measure deadlines with Stopwatch, not DateTime.UtcNow. For timing changes, repeat on Linux/two CPUs where available.</p><p>Verify game logic with isolated host/guest instances, separate savedata and a separate server/port. BridgeTools/RimBridge is an available development tool, not a release dependency. Record executed steps/results in the manual checklist; a written scenario alone is not PASS.</p><p>Wiki: test:checks → check:content → check:reference → check:drift -- --base &lt;commit&gt; → build → check:links, followed by real browser/search/mobile navigation.</p><h2 id="test-matrix" tabindex="-1">Which check answers which question? <a class="header-anchor" href="#test-matrix" aria-label="Permalink to &quot;Which check answers which question? {#test-matrix}&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Check</th><th>Establishes</th><th>Does not establish</th></tr></thead><tbody><tr><td>Solution build/tests</td><td>Core/server contracts, storage, boundary scenarios</td><td>Game UI/Scribe/pawns</td></tr><tr><td>Build-ClientMod</td><td>Compilation against installed game</td><td>A completed two-player flow</td></tr><tr><td>Two isolated clients</td><td>Execution of specified real steps</td><td>Every mod/DLC/GOG combination</td></tr><tr><td>Wiki validators/build</td><td>Structure, links, inventory</td><td>Semantic article accuracy</td></tr><tr><td>Browser acceptance</td><td>Search/navigation/layout at tested sizes</td><td>All browsers or actual OS zoom</td></tr></tbody></table><p>For a bugfix observe RED on the original case, then GREEN. Wait for received stream events, not Open returning. Use Stopwatch deadlines; repeat Linux/two-CPU checks for timing/race changes where available.</p><h2 id="acceptance-record" tabindex="-1">How do I record reproducible acceptance? <a class="header-anchor" href="#acceptance-record" aria-label="Permalink to &quot;How do I record reproducible acceptance? {#acceptance-record}&quot;">​</a></h2><p>Record commit, versions, separate DataDir/port, host/guest savedata and initial state. List actions, expected/observed results, operation IDs, return mail and save/relogin checks. A UI screenshot without server outcome does not prove escrow.</p><p>For coop test assigned/unassigned pawns, exit, revocation and rollback. For economy test unknown responses and original replay. Do not operate others&#39; games or clear shared Player.log. Mark unfinished scenarios partial, not PASS.</p><h2 id="limits" tabindex="-1">Limits and safety <a class="header-anchor" href="#limits" aria-label="Permalink to &quot;Limits and safety {#limits}&quot;">​</a></h2><p>Do not start another server against live data or stop someone else&#39;s game. Game instances may overwrite the shared Player.log. Never report an unrun check as successful.</p><h2 id="related" tabindex="-1">See also <a class="header-anchor" href="#related" aria-label="Permalink to &quot;See also {#related}&quot;">​</a></h2><ul><li><a href="./build">Building the project</a></li><li><a href="./contributing">Contributing and wiki maintenance</a></li><li><a href="./../admins/troubleshooting">Administrator troubleshooting</a></li></ul>',17)])])}const m=t(i,[["render",s]]);export{u as __pageData,m as default};
